# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Compute the AI centers-of-thought map from pinned OpenAlex responses.

    uv run scripts/centers_map.py targets            print every target row derivable from the pins so far
    uv run scripts/centers_map.py build [--out DIR]  write computed/*.tsv from the pins (default computed/)

Stdlib only. Reads only `.cache/` pins listed in MANIFEST.tsv; no network, no
clock, no randomness. Output rows are sorted, so a rebuild is byte-identical.

Workflow (run from resources/topologies/ai-centers/), repeated until `targets`
adds nothing new:

    uv run scripts/centers_map.py targets > /tmp/t.tsv   # then merge new rows into targets.tsv
    uv run scripts/pin.py pin

Stages: (1) static queries; (2) institution metadata lookups and per-institution
partner queries, both derived from the stage-1 pins.
"""
from __future__ import annotations

import argparse
import html.parser
import json
import sys
import urllib.parse
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CACHE = ROOT / ".cache"
API = "https://api.openalex.org"

# The scope. T10883 "Ethics and Social Impacts of AI" (subfield Safety Research)
# was the first hit for both the "ethics" and "fairness" topic searches pinned as
# q-topics-*; its OpenAlex keywords include AI ethics, AI governance, AI safety,
# AI alignment, AI policy, AI regulation and responsible AI. Choosing it is a
# proposal (witness llm:claude-opus-5-5 prompt=unrecorded), not a computation.
TOPICS = ["T10883"]
YEARS = "2021-2025"
BASE = f"primary_topic.id:{'|'.join(TOPICS)},publication_year:{YEARS}"

# Conference records: OpenAlex source ids are resolved from pinned searches.
VENUE_SEARCHES = {
    "facct": "Fairness, Accountability, and Transparency",
    "aies": "AI, Ethics, and Society",
}

# Region groups for per-region top-institution queries: M49 regions, with the
# Americas split by M49 sub-region and Asia by M49 sub-region, so that no large
# producer crowds a smaller one out of a 200-row page.
TOP_GLOBAL_PARTNERS = 20      # partner queries for the global top N institutions
TOP_REGION_PARTNERS = 3       # ... plus the top N of each region group not already covered
PAGE = 200


def q(path: str, **params: str) -> str:
    return f"{API}/{path}?" + "&".join(f"{k.replace('_', '-') if k == 'per_page' else k}={urllib.parse.quote(v, safe=':|,*-.')}"
                                      for k, v in params.items())


# ---------------------------------------------------------------- pins

def read_tsv(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        return []
    lines = path.read_text(encoding="utf-8").splitlines()
    head = lines[0].split("\t")
    return [dict(zip(head, ln.split("\t"))) for ln in lines[1:] if ln.strip()]


def manifest() -> dict[str, dict[str, str]]:
    return {r["id"]: r for r in read_tsv(ROOT / "MANIFEST.tsv")}


def pin_json(pid: str):
    m = manifest()
    if pid not in m:
        return None
    return json.loads((CACHE / f"{pid}.json").read_bytes())


class _Cells(html.parser.HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.in_table = False
        self.rows: list[list[str]] = []
        self.cell: list[str] | None = None

    def handle_starttag(self, tag, attrs):
        if tag == "table" and dict(attrs).get("id") == "downloadTableEN":
            self.in_table = True
        elif self.in_table and tag == "tr":
            self.rows.append([])
        elif self.in_table and tag == "td":
            self.cell = []

    def handle_endtag(self, tag):
        if tag == "table" and self.in_table:
            self.in_table = False
        elif tag == "td" and self.cell is not None:
            self.rows[-1].append(" ".join("".join(self.cell).split()))
            self.cell = None

    def handle_data(self, data):
        if self.cell is not None:
            self.cell.append(data)


def m49() -> dict[str, dict[str, str]]:
    """ISO alpha-2 -> {region, subregion, intermediate, name, ldc} from the pinned UNSD table."""
    p = _Cells()
    p.feed((CACHE / "m49-overview.html").read_bytes().decode("utf-8"))
    head, *body = p.rows
    out = {}
    for r in body:
        d = dict(zip(head, r))
        if d.get("ISO-alpha2 Code"):
            out[d["ISO-alpha2 Code"]] = {
                "region": d["Region Name"], "subregion": d["Sub-region Name"],
                "intermediate": d["Intermediate Region Name"], "name": d["Country or Area"],
                "ldc": "x" if d["Least Developed Countries (LDC)"] else "",
            }
    return out


def group_of(c: dict[str, str]) -> str:
    if c["region"] == "Americas":
        return "Latin America and the Caribbean" if c["subregion"] == "Latin America and the Caribbean" else "Northern America"
    if c["region"] == "Asia":
        return c["subregion"]
    return c["region"]


def region_groups() -> dict[str, list[str]]:
    g: dict[str, list[str]] = {}
    for iso, c in m49().items():
        g.setdefault(group_of(c), []).append(iso)
    return {k: sorted(v) for k, v in sorted(g.items())}


def slug(s: str) -> str:
    return "".join(ch.lower() if ch.isalnum() else "-" for ch in s).strip("-").replace("--", "-")


# ---------------------------------------------------------------- targets

def static_targets() -> list[tuple[str, str, str]]:
    t = [
        ("oa-years", q("works", filter=BASE, group_by="publication_year"), "works per year"),
        ("oa-countries", q("works", filter=BASE, group_by="authorships.countries:include_unknown", per_page="200"),
         "works per author country, unknown included"),
        ("oa-inst-global", q("works", filter=BASE, group_by="authorships.institutions.id:include_unknown", per_page=str(PAGE)),
         "top institutions, unknown included"),
        ("oa-oa-status", q("works", filter=BASE, group_by="open_access.is_oa"), "open-access share"),
        ("oa-language", q("works", filter=BASE, group_by="language"), "works per language"),
    ]
    for name, isos in region_groups().items():
        t.append((f"oa-inst-r-{slug(name)}",
                  q("works", filter=f"{BASE},authorships.countries:{'|'.join(isos)}",
                    group_by="authorships.institutions.id", per_page=str(PAGE)),
                  f"top institutions on works with any author in M49 group {name}"))
    for key, text in VENUE_SEARCHES.items():
        t.append((f"oa-src-{key}", q("sources", search=text, per_page="10",
                                     select="id,display_name,type,works_count,host_organization_name"),
                  f"source search: {text}"))
    return t


def venue_ids() -> dict[str, list[str]]:
    """Conference sources whose display name contains the searched phrase and whose type is conference."""
    out = {}
    for key, text in VENUE_SEARCHES.items():
        d = pin_json(f"oa-src-{key}")
        if d is None:
            continue
        ids = sorted(s["id"].rsplit("/", 1)[1] for s in d["results"]
                     if text.lower() in s["display_name"].lower() and s.get("type") == "conference")
        if ids:
            out[key] = ids
    return out


def inst_rows(pid: str) -> list[tuple[str, int]]:
    d = pin_json(pid)
    if d is None:
        return []
    return [(g["key"].rsplit("/", 1)[1], g["count"]) for g in d["group_by"]
            if g["key"] and "openalex.org/I" in g["key"]]


def region_pins() -> list[str]:
    return [f"oa-inst-r-{slug(n)}" for n in region_groups()]


def all_inst_ids() -> list[str]:
    ids = set(i for i, _ in inst_rows("oa-inst-global"))
    for p in region_pins():
        ids.update(i for i, _ in inst_rows(p))
    for key in venue_ids():
        ids.update(i for i, _ in inst_rows(f"oa-venue-inst-{key}"))
    return sorted(ids, key=lambda s: int(s[1:]))


def inst_meta() -> dict[str, dict]:
    out = {}
    for pid in sorted(manifest()):
        if pid.startswith("oa-instmeta-"):
            for r in pin_json(pid)["results"]:
                out[r["id"].rsplit("/", 1)[1]] = r
    return out


def ranked(rows: list[tuple[str, int]]) -> list[tuple[str, int]]:
    return sorted(rows, key=lambda r: (-r[1], int(r[0][1:])))


def partner_ids() -> list[str]:
    g = [i for i, _ in ranked(inst_rows("oa-inst-global"))][:TOP_GLOBAL_PARTNERS]
    meta = inst_meta()
    chosen = list(g)
    geo = m49()
    for name in region_groups():
        rows = ranked(inst_rows(f"oa-inst-r-{slug(name)}"))
        mine = [i for i, _ in rows if i in meta and geo.get(meta[i].get("country_code") or "", {}) and
                group_of(geo[meta[i]["country_code"]]) == name]
        for i in mine[:TOP_REGION_PARTNERS]:
            if i not in chosen:
                chosen.append(i)
    return chosen


def derived_targets() -> list[tuple[str, str, str]]:
    t = []
    for key, ids in venue_ids().items():
        vf = f"primary_location.source.id:{'|'.join(ids)},publication_year:{YEARS}"
        t.append((f"oa-venue-years-{key}", q("works", filter=vf, group_by="publication_year"), f"{key} works per year"))
        t.append((f"oa-venue-countries-{key}", q("works", filter=vf, group_by="authorships.countries:include_unknown", per_page="200"),
                  f"{key} works per author country"))
        t.append((f"oa-venue-inst-{key}", q("works", filter=vf, group_by="authorships.institutions.id:include_unknown", per_page=str(PAGE)),
                  f"{key} top institutions"))
    ids = all_inst_ids()
    if ids and (pin_json("oa-inst-global") is not None):
        for n in range(0, len(ids), 100):
            chunk = ids[n:n + 100]
            t.append((f"oa-instmeta-{n // 100:02d}",
                      q("institutions", filter="openalex:" + "|".join(chunk), per_page="100",
                        select="id,display_name,ror,country_code,type,lineage"),
                      "institution metadata (ROR, country, type)"))
