        for i in partner_ids():
            t.append((f"oa-partners-{i}",
                      q("works", filter=f"{BASE},authorships.institutions.id:{i}",
                        group_by="authorships.institutions.id", per_page=str(PAGE)),
                      f"co-authoring institutions of {i} (top {PAGE})"))
    return t


def cmd_targets(_a) -> int:
    rows = static_targets() + derived_targets()
    for pid, url, note in rows:
        print(f"{pid}\topenalex\t{url}\t{note}")
    return 0


# ---------------------------------------------------------------- build

def write(path: Path, cols: list[str], rows: list[list]) -> None:
    path.write_text("\n".join(["\t".join(cols)] + ["\t".join(str(x) for x in r) for r in rows]) + "\n", encoding="utf-8")


def total(pid: str) -> int:
    return pin_json(pid)["meta"]["count"]


def unknown(pid: str) -> int:
    return sum(g["count"] for g in pin_json(pid)["group_by"] if g["key"] in ("unknown", None, ""))


def pct(a: int, b: int) -> str:
    return f"{100 * a / b:.1f}" if b else "NA"


def cmd_build(a) -> int:
    out = Path(a.out)
    out.mkdir(parents=True, exist_ok=True)
    geo = m49()
    meta = inst_meta()

    def geo_cols(cc: str) -> list[str]:
        c = geo.get(cc)
        return [c["region"], group_of(c), c["subregion"]] if c else ["unmapped", "unmapped", "unmapped"]

    # -- coverage
    n = total("oa-years")
    cov = [
        ["scope", f"primary_topic.id in {'|'.join(TOPICS)}; publication_year {YEARS}", "", ""],
        ["works", n, n, "100.0"],
        ["works_with_any_institution", n - unknown("oa-inst-global"), n, pct(n - unknown("oa-inst-global"), n)],
        ["works_with_any_country", n - unknown("oa-countries"), n, pct(n - unknown("oa-countries"), n)],
    ]
    for g in sorted(pin_json("oa-years")["group_by"], key=lambda g: g["key"]):
        cov.append([f"works_{g['key']}", g["count"], n, pct(g["count"], n)])
    for g in sorted(pin_json("oa-oa-status")["group_by"], key=lambda g: g["key"]):
        cov.append([f"open_access_{g['key_display_name']}", g["count"], n, pct(g["count"], n)])
    langs = sorted(pin_json("oa-language")["group_by"], key=lambda g: (-g["count"], g["key"] or ""))
    for g in langs:
        cov.append([f"language_{g['key'] or 'unknown'}", g["count"], n, pct(g["count"], n)])
    write(out / "coverage.tsv", ["measure", "value", "denominator", "pct"], cov)

    # -- countries
    crow = []
    for g in pin_json("oa-countries")["group_by"]:
        if g["key"] in ("unknown", None, ""):
            continue
        cc = g["key"].rsplit("/", 1)[1]
        crow.append([cc, geo.get(cc, {}).get("name", g["key_display_name"]), *geo_cols(cc), g["count"], pct(g["count"], n)])
    crow.sort(key=lambda r: (-r[5], r[0]))
    write(out / "countries.tsv", ["iso2", "name", "m49_region", "group", "m49_subregion", "works", "pct_of_works"],
          [[i + 1, *r] for i, r in enumerate(crow)] and [r for r in crow])
    regions: dict[str, int] = {}
    groups: dict[str, int] = {}
    for r in crow:
        regions[r[2]] = regions.get(r[2], 0) + r[5]
        groups[r[3]] = groups.get(r[3], 0) + r[5]
    reg = [["m49_region", k, v, n, pct(v, n)] for k, v in regions.items()] + \
          [["group", k, v, n, pct(v, n)] for k, v in groups.items()]
    reg.sort(key=lambda r: (r[0], -r[2], r[1]))
    write(out / "regions.tsv", ["level", "name", "work_country_pairs", "works_denominator", "pct"], reg)

    # -- institutions: global and per region group
    def inst_line(i: str, cnt: int) -> list:
        m = meta.get(i, {})
        cc = m.get("country_code") or ""
        return [i, (m.get("ror") or "").replace("https://ror.org/", ""), m.get("display_name", ""), m.get("type", ""),
                cc, *geo_cols(cc), cnt]

    rows = []
    for k, (i, cnt) in enumerate(ranked(inst_rows("oa-inst-global")), 1):
        rows.append(["global", k, *inst_line(i, cnt)])
    for name in region_groups():
        k = 0
        for i, cnt in ranked(inst_rows(f"oa-inst-r-{slug(name)}")):
            line = inst_line(i, cnt)
            if line[6] != name:
                continue  # partner from another region on that region's works
            k += 1
            rows.append([name, k, *line])
    write(out / "institutions.tsv",
          ["list", "rank", "openalex_id", "ror", "name", "type", "country", "m49_region", "group", "m49_subregion", "works"], rows)

    # -- partners and edges
    pids = sorted(p for p in manifest() if p.startswith("oa-partners-"))
    focus = [p.split("-", 2)[2] for p in pids]
    deg, edges = [], {}
    for p, i in zip(pids, focus):
        d = pin_json(p)
        partners = [(g["key"].rsplit("/", 1)[1], g["count"]) for g in d["group_by"]
                    if g["key"] and "openalex.org/I" in g["key"]]
        own = d["meta"]["count"]
        distinct = d["meta"].get("groups_count")
        others = [x for x in partners if x[0] != i]
        collab = own - dict(partners).get(i, own)  # not derivable: kept for clarity below
        deg.append([*inst_line(i, own)[:5], own, (distinct - 1) if isinstance(distinct, int) else "NA",
                    len(others), "yes" if len(partners) >= PAGE else "no"])
        for j, c in others:
            a_, b_ = sorted((i, j), key=lambda s: int(s[1:]))
            edges[(a_, b_)] = max(edges.get((a_, b_), 0), c)
    deg.sort(key=lambda r: (-r[5], int(r[0][1:])))
    write(out / "partners.tsv", ["openalex_id", "ror", "name", "type", "country", "works",
                                 "distinct_coauthoring_institutions", "partners_listed", "partner_list_truncated"], deg)
    fs = set(focus)
    erows = [[a_, b_, meta.get(a_, {}).get("display_name", ""), meta.get(b_, {}).get("display_name", ""), c]
             for (a_, b_), c in edges.items() if a_ in fs and b_ in fs]
    erows.sort(key=lambda r: (-r[4], int(r[0][1:]), int(r[1][1:])))
    write(out / "coauthorship-edges.tsv", ["source", "target", "source_name", "target_name", "shared_works"], erows)

    # -- conferences
    vrows, vc = [], []
    for key, ids in venue_ids().items():
        if pin_json(f"oa-venue-years-{key}") is None:
            continue
        vn = total(f"oa-venue-years-{key}")
        vrows.append([key, "sources", "|".join(ids), "", "", "", "", "", "", vn])
        vrows.append([key, "works_with_any_institution", "", "", "", "", "", "", "",
                      vn - unknown(f"oa-venue-inst-{key}")])
        for k, (i, cnt) in enumerate(ranked(inst_rows(f"oa-venue-inst-{key}")), 1):
            l = inst_line(i, cnt)
            vrows.append([key, k, *[l[x] for x in (0, 1, 2, 4, 5, 6)], "", cnt])
        for g in pin_json(f"oa-venue-countries-{key}")["group_by"]:
            cc = "unknown" if g["key"] in ("unknown", None, "") else g["key"].rsplit("/", 1)[1]
            vc.append([key, cc, *(geo_cols(cc) if cc != "unknown" else ["unknown"] * 3), g["count"], vn, pct(g["count"], vn)])
    write(out / "venue-institutions.tsv",
          ["venue", "rank", "openalex_id", "ror", "name", "country", "m49_region", "group", "", "works"], vrows)
    vc.sort(key=lambda r: (r[0], -r[5], r[1]))
    write(out / "venue-countries.tsv", ["venue", "iso2", "m49_region", "group", "m49_subregion", "works", "venue_works", "pct"], vc)
    return 0


def main() -> int:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("targets").set_defaults(fn=cmd_targets)
    p = sub.add_parser("build"); p.add_argument("--out", default=str(ROOT / "computed")); p.set_defaults(fn=cmd_build)
    a = ap.parse_args()
    return a.fn(a)


if __name__ == "__main__":
    sys.exit(main())

