        t.append((f"oa-venue-years-{key}", q("works", filter=vf, group_by="publication_year"), f"{key} works per year"))
        t.append((f"oa-venue-countries-{key}", q("works", filter=vf, group_by="authorships.countries:include_unknown", per_page="200"),
                  f"{key} works per author country"))
        t.append((f"oa-venue-inst-{key}", q("works", filter=vf, group_by="authorships.institutions.id:include_unknown", per_page=str(PAGE)),
                  f"{key} top institutions"))
    ids = all_inst_ids()
    if ids and (pin_json("oa-inst-global") is not None):
        for n in range(0, len(ids), 100):
            chunk = ids[n:n + 100]
            t.append((f"oa-instmeta-{n // 100:02d}",
                      q("institutions", filter="openalex:" + "|".join(chunk), per_page="100",
                        select="id,display_name,ror,country_code,type,lineage"),
                      "institution metadata (ROR, country, type)"))
    if inst_meta():
        for i in partner_ids():
            t.append((f"oa-partners-{i}",
                      q("works", filter=f"{BASE},authorships.institutions.id:{i}",
                        group_by="authorships.institutions.id", per_page=str(PAGE)),
                      f"co-authoring institutions of {i} (top {PAGE})"))
