    for name, isos in region_groups().items():
        t.append((f"oa-inst-r-{slug(name)}",
                  q("works", filter=f"{BASE},authorships.countries:{'|'.join(isos)}",
                    group_by="authorships.institutions.id", per_page=str(PAGE)),
                  f"top institutions on works with any author in M49 group {name}"))
    for key, text in VENUE_SEARCHES.items():
        t.append((f"oa-src-{key}", q("sources", search=text, per_page="10",
                                     select="id,display_name,type,works_count,host_organization_name"),
                  f"source search: {text}"))
    return t


def venue_ids() -> dict[str, list[str]]:
    """Conference sources whose display name contains the searched phrase and whose type is conference."""
    out = {}
    for key, text in VENUE_SEARCHES.items():
        d = pin_json(f"oa-src-{key}")
        if d is None:
            continue
        ids = sorted(s["id"].rsplit("/", 1)[1] for s in d["results"]
                     if text.lower() in s["display_name"].lower() and s.get("type") == "conference")
        if ids:
            out[key] = ids
    return out


