    return [(g["key"].rsplit("/", 1)[1], g["count"]) for g in d["group_by"]
            if g["key"] and "openalex.org/I" in g["key"]]


def region_pins() -> list[str]:
    return [f"oa-inst-r-{slug(n)}" for n in region_groups()]


