    return sorted(ids, key=lambda s: int(s[1:]))


def inst_meta() -> dict[str, dict]:
    out = {}
    for pid in sorted(manifest()):
        if pid.startswith("oa-instmeta-"):
            for r in pin_json(pid)["results"]:
                out[r["id"].rsplit("/", 1)[1]] = r
    return out


def ranked(rows: list[tuple[str, int]]) -> list[tuple[str, int]]:
    return sorted(rows, key=lambda r: (-r[1], int(r[0][1:])))


def partner_ids() -> list[str]:
    g = [i for i, _ in ranked(inst_rows("oa-inst-global"))][:TOP_GLOBAL_PARTNERS]
